package cn.hydrogen.launcher;import android.content.*;public class CompanionService {public static int syncs;public static boolean warmAllowed;public static int startupPrepares;public static boolean prepareMusicDuringStartup(Context c,Config cfg){startupPrepares++;return warmAllowed&&c.startService(new Intent().setComponent(new ComponentName(cfg.pkg(true),"fixture.PublicService")))!=null;}public static void sync(Context c){syncs++;}public static void prewarm(Context c,Config cfg,boolean music){if(warmAllowed)c.startService(new Intent().setComponent(new ComponentName(cfg.pkg(music),"fixture.PublicService")));}}
